import json
# Construct the 5-item ordered-color stack, aligning the input's color-1 glyph to its third slot.
shape={0:[5,6],1:[4,7],2:[3,4,5,6,7,8]}
grid=[[0]*15 for _ in range(18)]
for band,color in enumerate([2,3,1,8,7]):
    for dr,cols in shape.items():
        for col in cols:
            grid[band*3+dr][col]=color
assert len(grid)==18 and all(len(row)==15 for row in grid)
assert [grid[6][5],grid[6][6],grid[7][4],grid[7][7]]==[1,1,1,1]
encoded=json.dumps({'action':'submit','grid':grid},separators=(',',':'))
assert len(json.loads(encoded)['grid'])==18
print(encoded)
